pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(name) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(name.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat:") {
        let sequence = sequence.parse::<u32>().map_err(|_| "invalid heartbeat sequence".to_string())?;
        return Ok(Msg::Heartbeat(sequence));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{name}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{sequence}"),
    }
}
pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_ping_frame_successfully() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_roundtrips_in_a_v2_envelope() {
        let message = Msg::Hello("Ada".into());
        assert_eq!(encode(&message), "v:2|hello:Ada");
        assert!(matches!(decode("v:2|hello:Ada"), Ok(Msg::Hello(name)) if name == "Ada"));
    }

    #[test]
    fn heartbeat_roundtrips_with_a_sequence_number() {
        let message = Msg::Heartbeat(42);
        assert_eq!(encode(&message), "v:2|heartbeat:42");
        assert!(matches!(decode("v:2|heartbeat:42"), Ok(Msg::Heartbeat(42))));
    }
}
